WITH deduped AS (SELECT id, cost, status FROM shipments QUALIFY ROW_NUMBER() OVER (PARTITION BY status ORDER BY shipped_date DESC, id) = 1) SELECT status, COUNT(*) FILTER (WHERE status = 'RETURNED') AS returned_rows, COUNT(*) AS row_count, COUNT(CASE WHEN status = 'LOST' THEN 1 END) AS lost_count, SUM(cost) FILTER (WHERE status = 'DELIVERED') AS delivered_total_cost, ROUND(AVG(cost), 2) AS avg_cost FROM deduped GROUP BY status HAVING COUNT(CASE WHEN status = 'LOST' THEN 1 END) >= 1
